use vstd::prelude::*;

verus! {
    fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[i] & b[i],
    {
        let n = a.len() as nat;
        let mut result: Vec<u8> = Vec::new();
        result.resize(n as usize, 0); // Initialize result with zeros

        let mut idx: nat = 0;
        while idx < n
            invariant
                idx <= n,
                result.len() == a.len(),
                forall|i: nat| 0 <= i < idx ==> result[i] == a[i] & b[i],
            decreases n - idx,
        {
            result[idx as usize] = a[idx as usize] & b[idx as usize];
            idx = idx + 1;
        }
        result
    }
}
